@props(['checkout' => false])
<div x-data x-init="$store.shop.loadCart()">
 <p role="status" x-show="$store.shop.cartLoading">Cargando bolsa…</p>
 <p class="ro-error" role="alert" x-show="$store.shop.cartError" x-text="$store.shop.cartError" x-cloak></p>
 <p class="page-note">Tu bolsa se guarda en este navegador. La disponibilidad se confirma al continuar con la compra.</p>
 <div class="blade-columns">
  <section class="blade-panel"><h2 class="text-xl font-bold mb-4">Tu equipo</h2><p class="store-empty" x-show="!$store.shop.cartLoading && !$store.shop.cartError && $store.shop.items.length === 0">Tu bolsa está vacía. <a class="underline" href="{{ route('store.catalog') }}">Explora el catálogo</a>.</p>
   <ul class="cart-list"><template x-for="product in $store.shop.items" :key="product.id"><li><div><a class="font-bold" :href="'/productos/' + encodeURIComponent(product.id)" x-text="product.name"></a><p class="page-note" x-text="$store.shop.price(product.prices[$store.shop.currency])"></p></div><div class="blade-actions"><button class="icon-button" :aria-label="'Restar ' + product.name" @click="$store.shop.change(product.id,-1)">−</button><span x-text="$store.shop.quantities[product.id]"></span><button class="icon-button" :aria-label="'Sumar ' + product.name" :disabled="$store.shop.quantities[product.id] >= $store.shop.limit(product)" @click="$store.shop.change(product.id,1)">+</button><button class="text-button" @click="$store.shop.change(product.id,'remove')">Quitar</button></div></li></template></ul>
